const icons={seo:Search,content:FileText,geo:Sparkles,performance:Gauge};
const loadingSteps=['Fetching page','Checking robots.txt and sitemap','Rendering','Scoring'];
const gradeFor=(score:number)=>score>=90?'A':score>=80?'B':score>=70?'C':score>=60?'D':'F';
type ActionDetail={why:string;change:string;example:string};
const actionDetail=(finding:Finding,audit:Audit):ActionDetail=>{
 const topic=audit.headings.find(heading=>heading.level===1)?.text||audit.preview.headline||'your primary page topic';
 const site=new URL(audit.url).hostname.replace(/^www\./,'');
 const shared={why:finding.category==='seo'?'This makes it easier for search engines and visitors to understand the page.':finding.category==='content'?'This helps visitors scan, understand, and trust the page.':'This makes the page’s useful information easier for systems to assess.'};
 const details:Record<string,ActionDetail>={
  'llms-txt':{why:'This is an optional publishing convention. Its presence is not evidence of better rankings or AI citations.',change:finding.recommendation,example:'No replacement is needed. Prioritize accessible, useful page content and clear crawler rules; add this file only if it serves your publishing workflow.'},
  title:{why:'The title is often the clearest label for a page in search results and browser tabs.',change:finding.recommendation,example:`Suggested pattern: “${topic} | ${site}”`},
  description:{why:'A useful description gives people a concise reason to choose this page when a search engine uses it.',change:finding.recommendation,example:`Suggested pattern: “Learn about ${topic} with clear details, practical next steps, and answers to common questions.”`},
  h1:{why:'A single, clear H1 tells visitors what the page is about as soon as they arrive.',change:finding.recommendation,example:`Example: <h1>${topic}</h1>`},
  outline:{why:'A logical heading order lets readers scan the page and makes sections easier to interpret.',change:finding.recommendation,example:'Example: H1 page topic → H2 main section → H3 detail within that section.'},
  links:{why:'Internal links guide visitors to the next useful page and prevent dead ends.',change:finding.recommendation,example:'Example: replace an outdated destination with the current service, category, or help page.'},
  copy:{why:'Visitors need enough useful context to decide whether this page answers their question.',change:finding.recommendation,example:'Example: add a short “who this is for,” “what to expect,” and “how it works” section.'},
  readability:{why:'Clear, direct language helps visitors understand the message without extra effort.',change:finding.recommendation,example:'Example: turn one long sentence into two short sentences, then define any specialist term.'},
  repetition:{why:'Repeated copy can hide the message and make the page feel less considered.',change:finding.recommendation,example:'Example: keep the strongest version once, then replace repeats with specific supporting detail.'},
  paragraphs:{why:'Shorter paragraphs make key points easier to find and digest.',change:finding.recommendation,example:'Example: introduce the point, explain it in two or three sentences, then use a list for details.'},
  'content-gaps':{why:'Pages are more useful when they address the questions visitors need answered before taking a next step.',change:finding.recommendation,example:'Example: add one researched customer question as a heading and answer it directly in the paragraph below.'},
  sections:{why:'Descriptive sections help a visitor move from an overview to the detail they need.',change:finding.recommendation,example:'Example: add H2 sections for benefits, process, proof, pricing, or next steps where relevant.'},
  answers:{why:'Direct answers near the question reduce friction for readers looking for a specific detail.',change:finding.recommendation,example:'Example: “How long does setup take?” followed by a two-sentence answer before the next heading.'},
  canonical:{why:'A canonical signal helps clarify the preferred URL when similar versions of a page exist.',change:finding.recommendation,example:`Example: <link rel="canonical" href="${audit.url}">`},
  alt:{why:'Text alternatives make informative images understandable when they cannot be seen.',change:finding.recommendation,example:'Example: alt="Marketing dashboard showing organic traffic growth by month".'},
  schema:{why:'Valid structured data reduces ambiguity about the type of information on the page.',change:finding.recommendation,example:'Example: add a valid Article, Product, FAQPage, or Organization JSON-LD block that matches visible copy.'},
  authorship:{why:'Clear author and date details help people judge the source and freshness of information.',change:finding.recommendation,example:'Example: “By Jordan Lee · Updated October 1, 2026” near the article heading.'},
  'page-speed':{why:'Slow initial delivery delays every visual and interactive step that follows.',change:finding.recommendation,example:'Example: cache the HTML response, remove an avoidable redirect, and reduce server work before rendering.'},
  'large-images':{why:'Oversized image downloads can delay the largest visible content and consume mobile data.',change:finding.recommendation,example:'Example: serve a 1200 px AVIF or WebP through srcset instead of a multi-megabyte original.'},
  'performance-bottlenecks':{why:'Blocking scripts and styles compete with the content visitors are waiting to see.',change:finding.recommendation,example:'Example: defer analytics and widgets, inline only critical CSS, and load the rest after the main content.'},
  'mobile-usability':{why:'Most visitors need the page to fit, wrap, and respond comfortably on a narrow screen.',change:finding.recommendation,example:'Example: width: 100%; max-width: 72rem; with 44 px primary controls and no horizontal scrolling.'},
  'core-web-vitals':{why:'LCP, INP, and CLS reflect loading speed, responsiveness, and visual stability experienced by real visitors.',change:finding.recommendation,example:'Example: validate lab LCP and CLS here, then confirm all three metrics with real-user field data.'},
 };
 return details[finding.id]||{...shared,change:finding.recommendation,example:`Improved version: make this page signal explicit and easy to verify in the HTML.`};
};
export default function Home(){
 const {history,record,clear,storageNote}=useAuditHistory();const [savedView,setSavedView]=useState(false);
 const [shareOpen,setShareOpen]=useState(false);
 const [audit,setAudit]=useState(sampleAudit); const [category,setCategory]=useState('all'); const [,setFilter]=useState('all');
 const [url,setUrl]=useState('');const [loading,setLoading]=useState(false);const [loadingStep,setLoadingStep]=useState(0);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [help,setHelp]=useState(false);const [renderToken,setRenderToken]=useState('');const [renderedWords,setRenderedWords]=useState<number|null>(sampleAudit.performance.lab?.renderedWords??null);const [labMetrics,setLabMetrics]=useState<LabPerformance|null>(sampleAudit.performance.lab);const [rendering,setRendering]=useState(false);const [previousAudit,setPreviousAudit]=useState<Audit|null>(null);const [shareUrl,setShareUrl]=useState('');const [companyName,setCompanyName]=useState('');const [logoDataUrl,setLogoDataUrl]=useState('');const active=useRef<AbortController|null>(null);const auditRef=useRef<Audit>(sampleAudit);
 const runAudit=useCallback(async(value:string)=>{
   if(active.current)throw new Error('An audit is already in progress.');
   if(typeof value!=='string'||!value.trim()||value.length>2048)throw new Error('Enter a valid website URL.');
   const controller=new AbortController();active.current=controller;setUrl(value);setLoading(true);setLoadingStep(0);setError('');setNotice('');const deadline=setTimeout(()=>controller.abort('timeout'),45000);const progressTimers=[900,2600,5200].map((delay,index)=>setTimeout(()=>setLoadingStep(index+1),delay));
   try{const response=await fetch('/api/audit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:value}),signal:controller.signal});const payload=await response.text();let result:Audit & {error?:string};try{result=JSON.parse(payload) as Audit & {error?:string};}catch{throw new Error('The audit service had a temporary problem. Please try again.');}if(!response.ok)throw new Error(result.error||'The audit could not be completed.');if(controller.signal.aborted)throw new Error('Audit canceled.');let stored:Audit[]=[];try{stored=parseHistory(localStorage.getItem(HISTORY_KEY)).audits;}catch{}const prior=earlierRun(stored,result);record(result);flushSync(()=>{if(typeof window!=='undefined'){const pageUrl=new URL(window.location.href);pageUrl.searchParams.delete('sample');window.history.replaceState(null,'',pageUrl.pathname+pageUrl.search+pageUrl.hash);}navigateWorkspace('overview',result.url);setPreviousAudit(prior);setSavedView(false);auditRef.current=result;setAudit(result);setShareUrl('');setCategory('all');setFilter('all');setNotice('Audit complete. Your report is ready.');});return result as Audit;}
   catch(e){const message=controller.signal.aborted?(controller.signal.reason==='timeout'?'This audit took too long. Please try again.':'Audit canceled.'):e instanceof Error?e.message:'The audit could not be completed.';setError(message);throw new Error(message);}
   finally{clearTimeout(deadline);progressTimers.forEach(clearTimeout);active.current=null;setLoading(false);}
 },[record]);
 // Hydrate the optional URL prefill after the server render.
 // eslint-disable-next-line react-hooks/set-state-in-effect
 useEffect(()=>{const supplied=new URLSearchParams(window.location.search).get('url');if(supplied){setUrl(supplied.slice(0,2048));try{const match=parseHistory(localStorage.getItem(HISTORY_KEY)).audits.find(item=>pageKey(item.url)===pageKey(supplied));if(match){setAudit(match);auditRef.current=match;setSavedView(true);}}catch{}}},[]);
 useEffect(()=>()=>active.current?.abort(),[]);
 useEffect(()=>{
   // Reset state when switching the external sandbox preview to the offline sample.
   // eslint-disable-next-line react-hooks/set-state-in-effect
   if(audit.sample||savedView){setRenderToken('');setLabMetrics(audit.performance.lab);setRenderedWords(audit.performance.lab?.renderedWords??null);setRendering(false);return;}
   const token=typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID().replace(/-/g,''):`render${Date.now()}${Math.random().toString(36).slice(2)}`;
   setRenderToken(token);setLabMetrics(null);setRenderedWords(null);setRendering(true);
   const onMessage=(event:MessageEvent)=>{const data=event.data as {type?:unknown;token?:unknown;metrics?:unknown};if(data?.type!=='signal-render-diagnostics'||data.token!==token||!data.metrics||typeof data.metrics!=='object')return;const metrics=data.metrics as LabPerformance;if(typeof metrics.renderedWords!=='number'||metrics.renderedWords<0||metrics.renderedWords>500000)return;const current=auditRef.current;if(current.url!==audit.url||current.date!==audit.date)return;setLabMetrics(metrics);setRenderedWords(Math.round(metrics.renderedWords));setRendering(false);const next={...current,performance:{...current.performance,lab:metrics}};auditRef.current=next;setAudit(next);record(next,true);};
   window.addEventListener('message',onMessage);const timeout=window.setTimeout(()=>setRendering(false),7500);
   return()=>{window.removeEventListener('message',onMessage);window.clearTimeout(timeout);};
 },[audit.url,audit.date,audit.sample,savedView,record]);
 useEffect(()=>{
   const context=(document as Document & {modelContext?:{registerTool:(tool:unknown,options:{signal:AbortSignal})=>void|Promise<void>}}).modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();
   try{Promise.resolve(context.registerTool({name:'run_website_audit',title:'Run website audit',description:'Fetch a public webpage and a focused sample of up to 8 internal links, then update the visible audit report. This sends the URL to the audit service and visits the public site.',inputSchema:{type:'object',properties:{url:{type:'string',description:'Public HTTP or HTTPS website URL'}},required:['url'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},async execute(input:unknown){if(!input||typeof input!=='object'||typeof (input as {url?:unknown}).url!=='string')throw new Error('A website URL is required.');const a=await runAudit((input as {url:string}).url);return {url:a.url,score:a.score,scores:a.scores,findings:a.findings.length,checkedLinks:a.metrics.checkedLinks};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}return ()=>lifecycle.abort();
 },[runAudit]);
 function downloadData(format:'json'|'csv'){const text=format==='json'?JSON.stringify(audit,null,2):auditCsv(audit.findings);const objectUrl=URL.createObjectURL(new Blob([text],{type:format==='json'?'application/json':'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=objectUrl;link.download=`signal-audit.${format}`;link.click();setTimeout(()=>URL.revokeObjectURL(objectUrl),1000);setNotice(`${format.toUpperCase()} report downloaded.`);}
 const branding={companyName,logoDataUrl};
 function download(){const blob=new Blob([reportHtml(audit,branding)],{type:'text/html;charset=utf-8'});const objectUrl=URL.createObjectURL(blob);const link=document.createElement('a');link.href=objectUrl;link.download=`signal-audit-${new URL(audit.url).hostname}${audit.sample?'-sample':''}.html`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(objectUrl),10000);setNotice('HTML report downloaded.');}
 function exportPdf(){const printable=window.open('','signal-audit-pdf','width=1000,height=800');if(!printable){setNotice('Allow pop-ups to export this report as a PDF.');return;}printable.document.write(reportHtml(audit,branding));printable.document.close();window.setTimeout(()=>{printable.focus();printable.print();},300);setNotice('Your print dialog is open. Choose “Save as PDF” to download the clean report.');}
 function chooseLogo(file:File|undefined){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1_000_000){setNotice('Choose a PNG, JPEG, or WebP logo smaller than 1 MB.');return;}const reader=new FileReader();reader.onload=()=>{if(typeof reader.result==='string')setLogoDataUrl(reader.result);};reader.onerror=()=>setNotice('We could not read that logo.');reader.readAsDataURL(file);}
 function permalink(){const link=`${window.location.origin}/report/${encodeShareSummary(summaryFromAudit(audit))}`;setShareUrl(link);return link;}
 async function copyShareLink(){try{const link=permalink();await navigator.clipboard.writeText(link);setNotice('Share link copied. It contains only the public URL, scores, and three fix titles.');}catch(error){setNotice(error instanceof Error?error.message:'We could not copy the share link.');}}
 function shareLinkedIn(){try{const link=permalink();window.open(`https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(link)}`,'_blank','noopener,noreferrer');setNotice('LinkedIn sharing opened in a new tab.');}catch(error){setNotice(error instanceof Error?error.message:'We could not open LinkedIn sharing.');}}
 async function downloadPng(){try{await downloadSharePng(summaryFromAudit(audit));setNotice('PNG summary downloaded.');}catch(error){setNotice(error instanceof Error?error.message:'We could not create the PNG.');}}
 function showSample(){active.current?.abort();if(typeof window!=='undefined')window.history.replaceState(null,'','?sample=1');auditRef.current=sampleAudit;setSavedView(false);setPreviousAudit(null);setShareUrl('');setAudit(sampleAudit);setCategory('all');setFilter('all');setError('');setNotice('Showing the offline sample report. No website was fetched.');document.getElementById('audit-overview')?.scrollIntoView({behavior:'smooth',block:'start'});}
 function runTestAudit(){void runAudit('https://example.com').catch(()=>{});}
 const reportLabel=audit.sample?'Illustrative results':new Date(audit.date).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});

 const wins=audit.findings.filter(f=>f.status==='good').slice(0,2);
 const needsAttention=prioritize(audit.findings).filter(isIssue).slice(0,2);
 const nextSteps=prioritize(audit.findings).filter(isIssue).slice(0,3);
 const actionItems=prioritize(audit.findings).filter(isIssue).slice(0,3);
 const topicSeeds=audit.keywords.slice(0,3).map(keyword=>keyword.word);
 const contentGap=audit.metrics.h2===0?'The page has no H2 sections yet. Start by separating the main promise, supporting detail, and next step.':audit.aiReadiness.questionHeadings===0?'No question-led sections were found. Research the questions customers ask before they buy, compare, or contact you.':'Use the existing sections as a map, then compare them with customer questions and competing pages to find a missing useful topic.';
 const grade=gradeFor(audit.score);const scoreRows=(Object.keys(categories) as Category[]).map(key=>({key,score:audit.scores[key],grade:gradeFor(audit.scores[key])}));
 const totals={critical:audit.findings.filter(f=>f.status==='critical').length,improvement:audit.findings.filter(f=>f.status==='improvement').length,good:audit.findings.filter(f=>f.status==='good').length};
 const topPriority=prioritize(audit.findings).find(isIssue);
 const rawHtmlWords=audit.metrics.rawHtmlWords;const clientRenderRisk=renderedWords!==null&&rawHtmlWords<80&&renderedWords>=Math.max(rawHtmlWords*2,120);
 const lcpState=labMetrics?.lcpMs===null||labMetrics?.lcpMs===undefined?'unknown':labMetrics.lcpMs<=2500?'good':labMetrics.lcpMs<=4000?'improvement':'critical';
 const clsState=labMetrics?.cls===null||labMetrics?.cls===undefined?'unknown':labMetrics.cls<=.1?'good':labMetrics.cls<=.25?'improvement':'critical';
 const mobileIssues=(labMetrics?.mobileOverflow?1:0)+(labMetrics?.smallTapTargets||0);
 const imageWarningCount=new Set([...audit.performance.largeImages.map(image=>image.url),...(labMetrics?.oversizedImages.map(image=>image.url)||[])]).size;
 const comparison=previousAudit&&pageKey(previousAudit.url)===pageKey(audit.url)?previousAudit:null;const runDiff=comparison?compareRuns(comparison,audit):null;const scoreDelta=comparison?audit.score-comparison.score:0;
 const focusFinding=(finding:{id:string;category:Category})=>{navigateWorkspace('recommendations',audit.url,finding.id);setCategory(finding.category);setFilter('all');setTimeout(()=>document.getElementById(`finding-${finding.id}`)?.scrollIntoView({behavior:'smooth',block:'center'}),0);};
 return <DashboardLayout audit={audit} url={url} onUrl={setUrl} onRun={()=>void runAudit(url).catch(()=>{})} onHelp={()=>setHelp(true)} onShare={()=>setShareOpen(true)} onExport={format=>format==='pdf'?exportPdf():format==='html'?download():downloadData(format as 'json'|'csv')} loading={loading}><div className="app-shell">
  <header className="site-header"><Link className="brand" href="/" aria-label="Signal home"><span className="brand-icon"><ChartNoAxesColumnIncreasing size={23}/></span>signal<span className="brand-period">.</span></Link><div className="header-section">Website intelligence</div><a className="github-link" href="https://github.com/shabeeh-shah/SEO-Audit-Tool" target="_blank" rel="noreferrer"><GitBranch size={16}/> View on GitHub</a><Button variant="ghost" className="help-button" onClick={()=>setHelp(true)}><CircleHelp/> How it works</Button></header>
  <div className="ws-content">
   <View views={['overview']}><section className="audit-starter"><div className="starter-copy"><div className="eyebrow"><span className="tiny-line"/> FIND YOUR NEXT OPPORTUNITY</div><h2>Find your next useful improvement.</h2><p>Check signals relevant to ChatGPT, Claude, and Perplexity—alongside SEO, content, and performance. See the evidence and draft your next fix.</p></div><form className="audit-form" onSubmit={e=>{e.preventDefault();void runAudit(url).catch(()=>{});}} aria-busy={loading}><label htmlFor="website-url">Website URL</label><div className="url-control"><Globe2 size={20}/><Input id="website-url" placeholder="https://yourwebsite.com" type="text" inputMode="url" autoComplete="url" value={url} onChange={e=>setUrl(e.target.value)} disabled={loading} aria-describedby="audit-note" maxLength={2048} required/><Button type="submit" disabled={loading}>{loading?<><LoaderCircle className="spin"/> Auditing…</>:<>Run audit <ArrowRight size={17}/></>}</Button></div><p id="audit-note">Public pages only · No ranking or AI-citation predictions · No server-side report storage</p><div className="quick-start"><span>Want to look around first?</span><Button type="button" variant="ghost" onClick={showSample} disabled={loading}><PlayCircle/> Preview offline sample</Button><Button type="button" variant="ghost" onClick={runTestAudit} disabled={loading}>Test example.com</Button></div>{loading&&<div className="ws-running" role="status" aria-live="polite"><ProgressSteps steps={loadingSteps} current={Math.min(loadingStep,1)}/><p>Fetching and rules checks are in progress. Browser rendering is measured separately after the page analysis; unavailable measurements stay unscored.</p><Skeleton label="Preparing audit results"/><Button type="button" variant="outline" onClick={()=>active.current?.abort()}>Cancel</Button></div>}{error&&<div className="ws-audit-error" role="alert"><strong>{error}</strong><p>{errorAdvice[auditErrorKind(error)]}</p><Button variant="outline" type="button" onClick={()=>void runAudit(url).catch(()=>{})}>Try again</Button></div>}</form></section></View>
   <div className="workspace">{notice&&<div className="notice" role="status"><Check size={16}/>{notice}<Button variant="ghost" size="icon-sm" aria-label="Dismiss notification" onClick={()=>setNotice('')}><X size={14}/></Button></div>}
    <View views={['overview']}><Card title="Your audit at a glance" className="ws-summary"><p className="ws-summary-url">{audit.url} · {reportLabel}</p><div className="ws-score-rings"><ScoreRing score={audit.score} label="Overall" onClick={()=>navigateWorkspace('scoring',audit.url)}/>{scoreRows.map(({key,score})=><ScoreRing key={key} score={score} label={categories[key]} onClick={()=>navigateWorkspace(key==='geo'?'ai-readiness':key==='performance'?'performance':'seo-content',audit.url)}/>)}</div></Card><Card title="Top 3 fixes"><div className="ws-fix-grid">{actionItems.map(f=><article key={f.id}><small>{priorityFor(f).impactLabel} impact · {priorityFor(f).effortLabel} effort</small><h3>{f.title}</h3><p>{f.recommendation}</p><Button variant="outline" onClick={()=>focusFinding(f)}>Open fix</Button></article>)}</div>{!actionItems.length&&<p>No open priority issues were found in these checks.</p>}</Card><Card title="Strengths to keep"><ul>{audit.findings.filter(f=>f.status==='good').slice(0,4).map(f=><li key={f.id}>✓ {f.title}</li>)}</ul></Card></View><View views={['overview']}><div className="report-heading" id="audit-overview"><div><div className="eyebrow light">YOUR WEBSITE, AT A GLANCE</div><h2>Audit overview <span className={'sample-badge '+(audit.sample?'':'live-badge')}>{audit.sample?'Sample report':savedView?'Saved audit':'Live audit'}</span></h2><p><Globe2 size={14}/> <span className="audited-url" title={audit.url}>{new URL(audit.url).hostname}{new URL(audit.url).pathname!=='/'?new URL(audit.url).pathname:''}</span> <span className="dot-separator">·</span> {reportLabel}</p></div><div className="report-actions">{!audit.sample&&<><Button variant="outline" onClick={shareLinkedIn}><Share2/> Share on LinkedIn</Button><Button variant="outline" onClick={()=>void copyShareLink()}><Link2/> Copy link</Button><Button variant="outline" onClick={()=>void downloadPng()}><ImageDown/> Download PNG</Button></>}<Button variant="outline" onClick={exportPdf}><Printer/> Export PDF</Button><Button variant="outline" onClick={download} aria-label="Download HTML report"><Download/> HTML</Button></div></div>{shareUrl&&<div className="share-link" role="status"><Share2 size={17}/><span>Stateless summary link. No report is stored server-side.</span><a href={shareUrl} target="_blank" rel="noreferrer">{shareUrl}</a><Button variant="ghost" size="icon-sm" aria-label="Copy report link" onClick={()=>void navigator.clipboard.writeText(shareUrl).then(()=>setNotice('Share link copied.')).catch(()=>setNotice('Copy the link shown in the report.'))}><Copy size={15}/></Button></div>}
    {savedView&&<div className="saved-report-note" role="status">You’re viewing a saved snapshot from {reportLabel}. Its results have not been refreshed.<Button variant="outline" disabled={loading||audit.sample} onClick={()=>void runAudit(audit.url).catch(()=>{})}>Run a new audit</Button></div>}
    <section className="executive-grid" aria-label="Audit brief" aria-busy={loading}>
      <article className="grade-card"><div className="grade-ring" style={{background:`conic-gradient(#2e7d6b ${audit.score}%, #dcebe6 0)`}}><div><strong>{grade}</strong><span>{audit.score}/100</span></div></div><div><span className="card-label">Overall grade</span><h3>{grade==='A'?'Excellent foundation':grade==='B'?'Strong foundation':grade==='C'?'Solid start, clear opportunities':grade==='D'?'Important improvements needed':'Start with the essentials'}</h3><p>Built from SEO, content, AI / GEO, and performance signals.</p></div></article>
      <article className="brief-card"><div className="brief-title"><div><span className="card-label">Your results, in brief</span><h3>{totals.good} wins, {totals.critical+totals.improvement} opportunities</h3></div><ChartNoAxesColumnIncreasing size={23}/></div><p>{topPriority?<>Start with <b>{topPriority.title.toLowerCase()}</b>. It is the clearest next move for this page.</>:<>This page is in good shape. Keep monitoring it as content and priorities change.</>}</p><div className="finding-distribution"><button className="good" onClick={()=>{setCategory('all');setFilter('good')}}><b>{totals.good}</b><span>Working</span></button><button className="improvement" onClick={()=>{setCategory('all');setFilter('improvement')}}><b>{totals.improvement}</b><span>Improve</span></button><button className="critical" onClick={()=>{setCategory('all');setFilter('critical')}}><b>{totals.critical}</b><span>Critical</span></button></div></article>
      <article className="visual-preview"><div className="preview-top"><span><i/><i/><i/></span><a href={audit.url} target="_blank" rel="noreferrer">Visit page <ExternalLink size={13}/></a></div><div className="preview-canvas">{audit.preview.image?<img src={audit.preview.image} alt={`Social preview for ${new URL(audit.url).hostname}`}/>:<div className="preview-fallback">{audit.preview.favicon&&<img src={audit.preview.favicon} alt=""/>}<span>{new URL(audit.url).hostname}</span><h3>{audit.preview.headline}</h3><p>{audit.description||'No meta description was found for this page.'}</p></div>}</div><p><FileText size={14}/> Visual preview from the page’s shared image or page details</p></article>
    </section></View>
    <View views={['overview']}><section className="score-section" aria-label="Score breakdown"><div className="score-section-heading"><div><span className="eyebrow light">YOUR SCORECARD</span><h2>See the full picture</h2><p>Grades make the strongest and weakest areas easier to compare.</p></div></div><div className="score-visuals"><div className="grade-breakdown">{scoreRows.map(({key,score,grade})=>{const Icon=icons[key];return <button key={key} className={'grade-row '+key+(category===key?' selected':'')} onClick={()=>{navigateWorkspace(key==='geo'?'ai-readiness':key==='performance'?'performance':'seo-content',audit.url);setCategory(key);setFilter('all')}}><span className="grade-letter">{grade}</span><span className={'category-icon '+key}><Icon size={18}/></span><span className="grade-copy"><b>{categories[key]}</b><small>{score}/100</small></span><Progress aria-label={categories[key]+' score'} value={score} className={'score-progress '+key}/><ArrowUpRight size={16}/></button>})}</div><div className="radar-card"><span>Balance across key areas</span><svg viewBox="0 0 220 180" role="img" aria-label={`SEO ${audit.scores.seo}, content ${audit.scores.content}, AI and GEO ${audit.scores.geo} out of 100`}><path className="radar-grid" d="M110 15 198 160 22 160Z M110 52 165 143 55 143Z M110 88 143 126 77 126Z"/><path className="radar-area" d={`M110 ${160-(145*audit.scores.seo/100)} ${110+(88*audit.scores.content/100)} ${160-(0*audit.scores.content/100)} ${110-(88*audit.scores.geo/100)} ${160-(0*audit.scores.geo/100)}Z`}/><circle cx="110" cy={160-(145*audit.scores.seo/100)} r="4"/><circle cx={110+(88*audit.scores.content/100)} cy="160" r="4"/><circle cx={110-(88*audit.scores.geo/100)} cy="160" r="4"/><text x="110" y="12" textAnchor="middle">SEO</text><text x="207" y="174" textAnchor="end">Content</text><text x="13" y="174">AI / GEO</text></svg></div></div></section></View>
    <View views={['scoring']}><ScoreCalculation audit={audit}/></View>
    <View views={['overview']}>{comparison&&runDiff&&<section className="comparison-panel" aria-label="Compare to previous audit"><div className="comparison-heading"><div><span className="eyebrow light">COMPARE TO PREVIOUS AUDIT</span><h2>What changed since your last run</h2><p>Compared with the most recent earlier saved audit of this exact page.</p></div><div className={'comparison-total '+(scoreDelta>0?'up':scoreDelta<0?'down':'flat')}>{scoreDelta>0?<TrendingUp size={18}/>:scoreDelta<0?<TrendingDown size={18}/>:<ChartNoAxesColumnIncreasing size={18}/>}<b>{scoreDelta>0?'+':''}{scoreDelta}</b><span>overall</span></div></div><div className="comparison-grid">{(['seo','content','geo','performance'] as Category[]).map(key=>{const delta=audit.scores[key]-comparison.scores[key];return <div key={key}><span>{categories[key]}</span><b>{audit.scores[key]}</b><small>was {comparison.scores[key]} · <em className={delta>0?'up':delta<0?'down':'flat'}>{delta>0?'+':''}{delta}</em></small></div>})}<div><span>Priority issues</span><b>{totals.critical+totals.improvement}</b><small>was {comparison.findings.filter(isIssue).length}</small></div></div><p>Resolved: {runDiff.resolved.map(f=>f.title).join(" · ")||"None"}</p><p>New issues: {runDiff.newIssues.map(f=>f.title).join(" · ")||"None"}</p>{!runDiff.comparable&&<p>Scoring coverage or version differs. Review individual findings before interpreting the score change.</p>}</section>}</View>
    <View views={['performance']}><section className="performance-section" aria-label="Performance and mobile"><div className="performance-heading"><div><span className="eyebrow light">PERFORMANCE &amp; MOBILE</span><h2>See what may be slowing the experience</h2><p>Server evidence and a 390 px browser lab snapshot. Use field data to confirm real-user Core Web Vitals.</p></div><Button variant="outline" onClick={()=>{focusFinding({id:'page-speed',category:'performance'});}}>View performance findings <ArrowRight size={16}/></Button></div><div className="performance-metrics"><article><Gauge size={18}/><span>Performance grade</span><b>{gradeFor(audit.scores.performance)}</b><small>{audit.scores.performance}/100 from scored checks</small></article><article><span>HTML response</span><b>{audit.metrics.responseMs.toLocaleString()} ms</b><small>{audit.metrics.htmlKb.toLocaleString()} KB of markup</small></article><article className={lcpState}><span>Lab LCP</span><b>{labMetrics?.lcpMs==null?'—':`${(labMetrics.lcpMs/1000).toFixed(2)} s`}</b><small>{rendering?'Measuring…':lcpState==='good'?'Good':lcpState==='improvement'?'Needs improvement':lcpState==='critical'?'Poor':'Unavailable'}</small></article><article className={clsState}><span>Lab CLS</span><b>{labMetrics?.cls==null?'—':labMetrics.cls.toFixed(3)}</b><small>{clsState==='good'?'Good':clsState==='improvement'?'Needs improvement':clsState==='critical'?'Poor':'Unavailable'}</small></article><article><Smartphone size={18}/><span>Mobile usability</span><b>{mobileIssues===0&&labMetrics?'Pass':labMetrics?'Review':'—'}</b><small>{labMetrics?`${labMetrics.mobileOverflow?'Horizontal overflow · ':''}${labMetrics.smallTapTargets} small tap target${labMetrics.smallTapTargets===1?'':'s'}`:'Lab preview unavailable'}</small></article><article><ImageIcon size={18}/><span>Image warnings</span><b>{imageWarningCount}</b><small>{audit.performance.checkedImages.length} files sampled · size and dimensions checked</small></article></div><p className="ws-range-note">Lab ranges: LCP good ≤ 2.5 s, needs improvement ≤ 4 s, poor &gt; 4 s. CLS good ≤ 0.1, needs improvement ≤ 0.25, poor &gt; 0.25. Confirm real-user experience with field data below.</p><div className="performance-detail"><span>FCP: {labMetrics?.fcpMs==null?'—':`${(labMetrics.fcpMs/1000).toFixed(2)} s`}</span><span>Lab load: {labMetrics?.loadMs==null?'—':`${(labMetrics.loadMs/1000).toFixed(2)} s`}</span><span>Long tasks: {labMetrics?.longTasks??'—'}</span><span>Transfer observed: {labMetrics?.transferKb==null?'—':`${labMetrics.transferKb.toLocaleString()} KB`}</span><span>INP: requires real interaction</span></div></section></View>
    <View views={['performance']}><section className="signal-extras" aria-label="Accessibility diagnostics"><h2>Accessibility: automated first pass</h2><p>axe-core checks the isolated preview against WCAG A/AA rules. This is a partial automated check, not a compliance verdict. Restricted resources can affect results.</p>{labMetrics?.accessibility?<><p>{labMetrics.accessibility.violations.length} rule violations shown · {labMetrics.accessibility.incomplete} rules need manual review.</p>{labMetrics.accessibility.violations.map(item=><article key={item.id}><strong>{item.impact||'Review'}: {item.help}</strong><p>{item.count} affected elements in the preview.</p><a href={item.url} target="_blank" rel="noreferrer">How to fix this rule ↗</a></article>)}</>:<p>{audit.sample?'Run a live audit for accessibility diagnostics.':'Accessibility results are pending or unavailable in this preview.'}</p>}</section></View>
    <View views={['seo-content','performance']}><section className={'rendering-diagnostic '+(clientRenderRisk?'warning':'')} aria-label="Client-rendering diagnostic"><div className="rendering-copy"><span className="eyebrow light">CONTENT DELIVERY</span><h2>{clientRenderRisk?'Much of this page appears after JavaScript runs':'Server-delivered content check'}</h2><p>{clientRenderRisk?'The isolated browser preview found substantially more readable text than the initial HTML.':'Compare the source received by the audit with text exposed after the page runs in an isolated browser preview.'}</p></div><div className="rendering-counts"><div><span>Server HTML text</span><b>{rawHtmlWords.toLocaleString()}</b><small>words used by this audit</small></div><div><span>Browser-rendered DOM</span><b>{renderedWords===null?'—':renderedWords.toLocaleString()}</b><small>{rendering?'Measuring isolated preview…':renderedWords===null?'Unavailable in this preview':'words after page scripts run'}</small></div><div><span>Script tags</span><b>{audit.metrics.scriptCount}</b><small>in the initial HTML</small></div></div>{clientRenderRisk&&<div className="client-render-warning"><AlertCircle size={19}/><span><b>Potential client-rendering risk.</b> Crawlers that do not execute, or do not finish executing, JavaScript may see less content than visitors do. This is a diagnostic signal, not proof of what any crawler will render.</span></div>}{audit.sample?<p className="rendering-note">Sample lab values are illustrative. Run a live audit for a fresh browser measurement.</p>:!savedView&&renderToken&&<iframe className="rendered-dom-frame" title="Isolated mobile lab measurement" aria-hidden="true" tabIndex={-1} sandbox="allow-scripts" src={`/api/render?url=${encodeURIComponent(audit.url)}&token=${encodeURIComponent(renderToken)}`}/>}</section></View>
    <View views={['overview']}><section className="direction-grid" aria-label="Audit priorities">
      <article className="direction-card working"><div className="direction-heading"><span className="direction-icon"><Check size={17}/></span><div><p>What’s working</p><h3>{wins.length} foundation{wins.length===1?'':'s'} to keep</h3></div></div><ul>{wins.map(f=><li key={f.id}><button onClick={()=>focusFinding(f)}>{f.title}<ArrowUpRight size={13}/></button></li>)}{wins.length===0&&<li>Run a live audit to identify positive signals.</li>}</ul></article>
      <article className="direction-card attention"><div className="direction-heading"><span className="direction-icon"><AlertCircle size={17}/></span><div><p>Needs attention</p><h3>{needsAttention.length} high-impact area{needsAttention.length===1?'':'s'}</h3></div></div><ul>{needsAttention.map(f=><li key={f.id}><button onClick={()=>focusFinding(f)}>{f.title}<ArrowUpRight size={13}/></button></li>)}{needsAttention.length===0&&<li>No urgent issues were found.</li>}</ul></article>
      <article className="direction-card next"><div className="direction-heading"><span className="direction-icon"><ArrowRight size={17}/></span><div><p>Next steps</p><h3>Start here</h3></div></div><ol>{nextSteps.map(f=><li key={f.id}><button onClick={()=>focusFinding(f)}>{f.recommendation}<ArrowRight size={13}/></button></li>)}{nextSteps.length===0&&<li>Keep monitoring this page as it changes.</li>}</ol></article>
    </section></View>
    <View views={['overview']}><section className="action-plan" aria-label="Action plan"><div className="action-plan-heading"><div><span className="eyebrow light">FROM ANALYSIS TO ACTION</span><h2>Make the next improvement easier to do</h2><p>Each recommendation explains the impact, the specific change, and a useful starting point. Examples are patterns to adapt to your brand, not copy to use unchanged.</p></div></div><div className="action-card-grid">{actionItems.map(finding=>{const action=actionDetail(finding,audit);return <article key={finding.id} className={'action-card '+finding.status}><div className="action-card-top"><small>{priorityFor(finding).impactLabel} estimated impact · {priorityFor(finding).effortLabel} effort</small><span className={'status-badge '+finding.status}>{finding.status==='critical'?'Critical':'Improvement'}</span><button onClick={()=>focusFinding(finding)}>Open check <ArrowRight size={13}/></button></div><h3>{finding.title}</h3><dl><div><dt>Why it matters</dt><dd>{action.why}</dd></div><div><dt>What to change</dt><dd>{action.change}</dd></div><div><dt>What a better version could look like</dt><dd className="action-example">{action.example}</dd></div></dl></article>})}{actionItems.length===0&&<article className="action-card good"><h3>Keep the foundation strong</h3><p>There are no open issues in this report. Re-run the audit after meaningful page changes and compare the results.</p></article>}</div><div className="opportunity-grid"><article><span>Keyword opportunities</span><h3>Turn topics into research questions</h3><p>{topicSeeds.length?`Start with the page’s recurring topics: ${topicSeeds.join(', ')}. Check customer language, search demand, and the intent behind each phrase before adding or changing copy.`:'This page does not have enough extracted text to suggest topic seeds. Start with customer questions and the language they use to describe the problem.'}</p></article><article><span>Internal linking</span><h3>Connect the next useful page</h3><p>{audit.metrics.links?`This page exposes ${audit.metrics.links} internal link${audit.metrics.links===1?'':'s'}. Link from relevant explanatory copy to the next service, product, proof, or help page—using descriptive anchor text.`:'No eligible internal links were found. Add a contextual link where it helps a reader continue their journey.'}</p></article><article><span>Content gaps</span><h3>Find the missing helpful topic</h3><p>{contentGap}</p></article></div></section></View>
    <View views={['ai-readiness']}><section className="ai-readiness-section" aria-label="AI search readiness"><div className="ai-readiness-heading"><div><span className="eyebrow light">AI SEARCH READINESS</span><h2>Make your public information easier to assess</h2><p>These checks show the signals a crawler can see. They do not predict or guarantee AI citations.</p></div><Button variant="outline" onClick={()=>{focusFinding({id:'ai-crawlers',category:'geo'});}}>View AI findings <ArrowRight size={16}/></Button></div><div className="ai-readiness-grid"><article><div className="ai-card-heading"><Sparkles size={18}/><div><h3>AI crawler access</h3><p>Rules found in robots.txt</p></div></div><table className="ws-bot-table"><caption>robots.txt access signals</caption><thead><tr><th>Crawler</th><th>Rule source</th><th>Access</th></tr></thead><tbody>{audit.aiReadiness.bots.map(bot=><tr key={bot.bot}><th scope="row">{bot.bot}</th><td>{bot.source}</td><td><span className={'ds-status '+(bot.state==='allowed'?'good':bot.state==='blocked'?'improvement':'optional')}>{bot.state==='allowed'?'✓ Allowed':bot.state==='blocked'?'! Blocked':'○ Unknown'}</span></td></tr>)}</tbody></table></article><article><div className="ai-card-heading"><FileText size={18}/><div><h3>Publisher signals</h3><p>Structured data</p></div></div><dl className="ai-signal-list"><div><dt>JSON-LD</dt><dd>{audit.aiReadiness.jsonLdBlocks} block{audit.aiReadiness.jsonLdBlocks===1?'':'s'} · {audit.aiReadiness.invalidJsonLd} error{audit.aiReadiness.invalidJsonLd===1?'':'s'}</dd></div><div><dt>Relevant types</dt><dd>{audit.aiReadiness.relevantSchemaTypes.join(', ')||'None found'}</dd></div></dl></article><article><div className="ai-card-heading"><Check size={18}/><div><h3>Answer and trust signals</h3><p>Clear answers and context</p></div></div><dl className="ai-signal-list"><div><dt>Question headings</dt><dd>{audit.aiReadiness.questionHeadings}</dd></div><div><dt>Concise answers</dt><dd>{audit.aiReadiness.conciseAnswers}</dd></div><div><dt>Author signals</dt><dd>{audit.aiReadiness.authorSignals.join(', ')||'None found'}</dd></div><div><dt>Date signals</dt><dd>{audit.aiReadiness.dateSignals.join(', ')||'None found'}</dd></div></dl></article></div></section></View>
    <View views={['ai-readiness']}><section className="optional-signals" aria-label="Optional signals"><div><span className="eyebrow light">OPTIONAL SIGNALS</span><h2>Experimental publishing conventions</h2><p>These signals are shown for context and do not affect any score.</p></div><article><div><FileText size={18}/><span><b>llms.txt · Experimental</b><small>{audit.aiReadiness.llmsTxt.url}</small></span></div><strong>{audit.aiReadiness.llmsTxt.status===null?'No response':`HTTP ${audit.aiReadiness.llmsTxt.status}`}</strong><p>llms.txt is optional and experimental. Its presence does not guarantee discovery, rankings, use, or AI citations, and its absence is not treated as an audit problem.</p></article></section></View>
    <div className="report-columns"><View views={['recommendations']}><Recommendations audit={audit} detail={finding=>actionDetail(finding,audit)}/></View>
     <View views={['seo-content']}><SeoContent audit={audit}/><aside className="report-aside"><section className="snapshot-panel"><div className="panel-heading"><h2>Page details</h2><FileText size={18}/></div><dl>{[['Word count',audit.metrics.words.toLocaleString()],['Reading ease',audit.metrics.readingEase===null?'Not scored':`${audit.metrics.readingEase} / 100`],['Heading structure',`${audit.metrics.h1} H1 · ${audit.metrics.h2} H2`],['Images without alt',`${audit.metrics.missingAlt} of ${audit.metrics.images}`],['Internal links checked',`${audit.metrics.checkedLinks} of ${audit.metrics.links}`],['Redirects before page',`${audit.metrics.redirects}`],['robots.txt',audit.metrics.robotsTxt.status===null?'No response':`HTTP ${audit.metrics.robotsTxt.status}`],['sitemap.xml',audit.metrics.sitemapXml.status===null?'No response':`HTTP ${audit.metrics.sitemapXml.status}`],['HTML response',`${audit.metrics.responseMs.toLocaleString()} ms`],['HTML size',`${audit.metrics.htmlKb} KB`]].map(([label,value])=><div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl><p className="snapshot-note">Response time covers HTML retrieval, not browser speed or Core Web Vitals.</p><div className="keywords"><h3>Topics found in copy</h3><div>{audit.keywords.map(k=><span key={k.word} title={`${k.count} occurrences · ${k.density}% of extracted words`}>{k.word} <b>{k.count}</b></span>)}{audit.keywords.length===0&&<p>Not enough text to identify topics.</p>}</div><p className="topic-note">Frequency is descriptive, not a keyword target.</p></div><div className="outline-wrap"><Accordion type="single" collapsible><AccordionItem value="outline"><AccordionTrigger>Heading outline</AccordionTrigger><AccordionContent><ol className="heading-outline">{audit.headings.map((h,i)=><li key={i}><b>H{h.level}</b>{h.text||'(empty heading)'}</li>)}{audit.headings.length===0&&<li>No headings found.</li>}</ol></AccordionContent></AccordionItem><AccordionItem value="links"><AccordionTrigger>Internal-link results</AccordionTrigger><AccordionContent><ul className="link-results">{audit.linkResults.map(l=><li key={l.url}><span>{l.url}</span><b className={l.state}>{l.status||'—'} · {l.state==='unknown'?'Inconclusive':l.state==='broken'?'Broken':'Reachable'}{l.redirects?` · ${l.redirects} redirect${l.redirects===1?'':'s'}`:''}</b></li>)}{audit.linkResults.length===0&&<li>{audit.sample?'Run a live audit to inspect links.':'No eligible internal links were found.'}</li>}</ul></AccordionContent></AccordionItem></Accordion></div></section><section className="insight-card"><span className="insight-icon"><Sparkles size={19}/></span><h3>Good for people.<br/>Clear for search.</h3><p>The strongest foundations are the same: useful content, clear structure, and answers worth finding.</p><span>Clarity is your advantage <ArrowUpRight size={16}/></span></section></aside></View>
    </div><View views={['checks']}><section className="scope-note"><Info size={17}/><div><strong>{audit.sample?'You’re viewing an illustrative sample. Enter a URL above for a live audit.':'A focused audit, with a clear scope.'}</strong><p>We inspect server-delivered HTML and sampled internal links. Scores are heuristic indicators, not search rankings, Core Web Vitals, or AI citation predictions. <button onClick={()=>setHelp(true)}>About the checks</button></p></div></section><footer className="report-footer"><span><span className="footer-brand">signal.</span> Less guesswork. Better websites.</span><span>Heuristic scores · One-page analysis</span></footer></View>
   </div>
   <div className="workspace"><View views={['overview']}><section className="signal-extras report-tools professional-exports" aria-label="Professional report downloads"><div><span className="eyebrow light">PROFESSIONAL OUTPUTS</span><h2>Your reports, ready to share</h2><p>Add optional client branding to the PDF and HTML cover. The report includes a one-page executive summary and a prioritized fix list.</p></div><div className="branding-controls"><label>Company name<Input value={companyName} onChange={event=>setCompanyName(event.target.value.slice(0,100))} maxLength={100} placeholder="Client or company name"/></label><label className="branding-logo">Client logo<input type="file" accept="image/png,image/jpeg,image/webp" onChange={event=>chooseLogo(event.target.files?.[0])}/>{logoDataUrl&&<span>Logo ready · <button type="button" onClick={()=>setLogoDataUrl('')}>Remove</button></span>}</label></div><small>Branding stays in this browser tab and is embedded only in the generated file. Signal does not upload or store it.</small><div className="signal-tools"><Button onClick={exportPdf}><Printer/> White-label PDF</Button><Button variant="outline" onClick={download}><Download/> HTML</Button><Button variant="outline" onClick={()=>downloadData('json')}><Download/> JSON</Button><Button variant="outline" onClick={()=>downloadData('csv')}><Download/> CSV</Button></div></section></View><View views={['bulk']}><BulkAudit/></View><View views={['history']}><AuditHistory history={history} currentUrl={audit.url} storageNote={storageNote} busy={loading} onRun={value=>void runAudit(value).catch(()=>{})} onClear={clear} onOpen={item=>{setSavedView(true);setPreviousAudit(earlierRun(history,item));setAudit(item);auditRef.current=item;setUrl(item.url);setShareUrl('');setCategory('all');setFilter('all');setError('');document.getElementById('audit-overview')?.scrollIntoView({behavior:'smooth',block:'start'});}}/></View><View views={['performance']}><FieldData key={'field'+audit.date} url={audit.url} sample={audit.sample}/></View><View views={['pages']}><SiteDiscovery key={'crawl'+audit.date} url={audit.url} sample={audit.sample}/></View><View views={['seo-content','ai-readiness']}><FixGenerators key={'fix'+audit.date} audit={audit}/></View><View views={['checks']}><ProductInfo/></View></div>
   <div className="workspace"><View views={['competitors']}><CompetitorInsights key={audit.url+audit.date} url={audit.url} sample={audit.sample} disabled={loading}/></View></div>
  </div>
  <Dialog open={shareOpen} onOpenChange={setShareOpen}><DialogContent><DialogHeader><DialogTitle>Share this audit</DialogTitle><DialogDescription>{audit.sample?'This is an illustrative sample.':'The link contains the public URL, scores, and top three fix titles. No report is stored server-side.'}</DialogDescription></DialogHeader><Button variant="outline" onClick={()=>void copyShareLink()}>Copy link</Button><Button variant="outline" onClick={shareLinkedIn}>Share on LinkedIn</Button><Button variant="outline" onClick={()=>void downloadPng()}>Download scorecard PNG</Button>{shareUrl&&<input aria-label="Share URL" readOnly value={shareUrl}/>}</DialogContent></Dialog>
  <Dialog open={help} onOpenChange={setHelp}><DialogContent className="method-dialog"><DialogHeader><DialogTitle>What your audit tells you</DialogTitle><DialogDescription>A focused review of one public page, with evidence you can act on.</DialogDescription></DialogHeader><div className="method-content"><h3>Four perspectives</h3><p><b>SEO foundations</b> checks title tags, meta robots and noindex, canonicals, heading order, viewport and language tags, Open Graph and Twitter cards, robots.txt and sitemap.xml availability, redirects, and a focused sample of up to 8 same-origin links.</p><p><b>Content quality</b> looks at extracted text, English reading ease, paragraph length, and repeated sentences. Word counts and readability are editorial aids, not ranking targets.</p><p><b>AI / GEO readiness</b> checks basic robots.txt rules for five public AI crawlers, llms.txt availability, JSON-LD syntax and relevant types, question-led answers, and author/date signals. These are transparency and structure signals, not a prediction of AI use or citations.</p><p><b>Performance and mobile</b> reviews initial HTML delivery, sampled image file sizes, render-blocking markup, responsive foundations, and a 390 px isolated browser snapshot for LCP, CLS, FCP, load timing, overflow, tap targets, and oversized image dimensions.</p><h3>Site-wide audit</h3><p>The separate sitemap-first crawler checks up to 10, 25, or 50 same-origin pages with bounded concurrency, one temporary-failure retry, robots.txt enforcement, per-page evidence, and a site summary. Cross-page findings only describe URLs included in that crawl.</p><h3>How scores work</h3><p>Each scored check is weighted: Good = 100, Improvement = 55, Critical = 0. Category scores are weighted averages; overall health averages SEO, Content, AI/GEO, and Performance. Advisory checks remain visible but do not change the score.</p><h3>What is not measured</h3><p>The browser measurements are lab diagnostics from one isolated run. Real-user field data is requested separately from CrUX when configured, and INP is not simulated because it requires real interaction. Search indexing, backlinks, traffic, pages beyond the selected crawl limit, and actual AI citations are not measured. Link health, image sizes, redirects, security headers, and accessibility checks remain bounded diagnostics.</p><h3>Your report</h3><p>Export downloads a standalone HTML report containing every finding, including hidden filters and available lab metrics. Open it in a browser to read offline or print to PDF.</p><p className="source-links"><a href="https://developers.google.com/search/docs/fundamentals/seo-starter-guide" target="_blank" rel="noreferrer">Google SEO guidance ↗</a><a href="https://web.dev/articles/vitals" target="_blank" rel="noreferrer">Web Vitals guidance ↗</a><a href="https://developers.google.com/search/docs/fundamentals/ai-optimization-guide" target="_blank" rel="noreferrer">Google AI guidance ↗</a><a href="https://www.w3.org/WAI/tutorials/images/" target="_blank" rel="noreferrer">W3C alt-text guidance ↗</a></p></div></DialogContent></Dialog>
 </div></DashboardLayout>
}
